item.text:
[
  {
    "task_id": "ctx-k7-3",
    "params": {
      "keysel": [0, 0, 0, 0, 0, 0, 0, 9],
      "bg": [9, 0, 0, 0, 0, 0, 0, 0, 0, 0]
    },
    "rationale": "Use colour and coordinates modulo 3. In demonstration 8, zeros at (0,1), (0,2), (0,4), and (3,2) become 8; (2,2) and (5,2) become 5; (5,1) becomes 2. Coordinates are zero-based."
  },
  {
    "task_id": "ctx-k1-1",
    "params": {
      "keysel": [0, 9, 0, 0, 0, 0, 0, 0],
      "bg": [9, 0, 0, 0, 0, 0, 0, 0, 0, 0]
    },
    "rationale": "Use own colour and the row's nonzero colour set. Demonstration 1 fills zeros with 2 in rows containing only 2, changes 3 to 4 in rows containing {2,3}, and changes zero to 6 and 3 to 8 in the row containing {1,2,3}."
  },
  {
    "task_id": "ctx-k1-2",
    "params": {
      "keysel": [0, 9, 0, 0, 0, 0, 0, 0],
      "bg": [9, 0, 0, 0, 0, 0, 0, 0, 0, 0]
    },
    "rationale": "Use own colour and the row's nonzero colour set. Demonstration 2 changes zeros to 4 for {1,2}, zeros to 7 for {1,3} or {2}, and 3 to 0 for {1,2,3}; rows containing {2,3} stay unchanged."
  },
  {
    "task_id": "ctx-k4-2",
    "params": {
      "keysel": [0, 0, 0, 0, 9, 0, 0, 0],
      "bg": [9, 0, 0, 0, 0, 0, 0, 0, 0, 0]
    },
    "rationale": "Use own colour and coordinate parity. Demonstration 2 changes zero to 4 and 2 to 1 at even-row, odd-column positions, 3 to 0 at even-row, even-column positions, and 2 to 4 at odd-row, even-column positions."
  },
  {
    "task_id": "ctx-k4-0",
    "params": {
      "keysel": [0, 0, 0, 0, 9, 0, 0, 0],
      "bg": [9, 0, 0, 0, 0, 0, 0, 0, 0, 0]
    },
    "rationale": "Use own colour and coordinate parity. Demonstration 1 changes 3 to 1 at even/even positions, zero to 2 at even/odd positions, and zero to 9 or 2 to 6 at odd/even positions."
  },
  {
    "task_id": "ctx-k6-2",
    "params": {
      "keysel": [0, 0, 0, 0, 0, 0, 9, 0],
      "bg": [9, 0, 0, 0, 0, 0, 0, 0, 0, 0]
    },
    "rationale": "Use own colour and the nearest nonzero colours in four directions. Demonstration 5 changes (0,2) from 0 to 1 with nearest down colour 3 and left colour 1; demonstration 3 changes (0,3) from 0 to 6 with nearest down colour 1 and left colour 2. Both have no nonzero colour above or right."
  },
  {
    "task_id": "ctx-k3-2",
    "params": {
      "keysel": [0, 0, 0, 9, 0, 0, 0, 0],
      "bg": [9, 0, 0, 0, 0, 0, 0, 0, 0, 0]
    },
    "rationale": "Use own colour and both row and column nonzero sets. Demonstration 1 changes 1 at (2,3) to 6 and 2 at (3,5) to 3 where both sets are {1,2,3}. Demonstration 6 changes zeros at (3,3) and (5,3) to 6 where the row set is {1,3} and column set is {3}."
  },
  {
    "task_id": "ctx-k6-0",
    "params": {
      "keysel": [0, 0, 0, 0, 0, 0, 9, 0],
      "bg": [9, 0, 0, 0, 0, 0, 0, 0, 0, 0]
    },
    "rationale": "Use own colour and nearest nonzero colours in four directions. Demonstration 1 changes zero at (2,5) to 6 with nearest colours up 2, down 2, left 2, right absent. Demonstration 7 changes (1,0) and (2,0) to 3 with up absent, down 2, left absent, right 3."
  },
  {
    "task_id": "ctx-k7-2",
    "params": {
      "keysel": [0, 0, 0, 0, 0, 0, 0, 9],
      "bg": [9, 0, 0, 0, 0, 0, 0, 0, 0, 0]
    },
    "rationale": "Use own colour and coordinates modulo 3. Demonstration 6 changes zeros in row residue 1, column residue 1 to 3; in row residue 2, column residues 0, 1, and 2 they become 7, 9, and 1 respectively. Zeros in row residue 0 remain zero."
  },
  {
    "task_id": "ctx-k4-1",
    "params": {
      "keysel": [0, 0, 0, 0, 9, 0, 0, 0],
      "bg": [9, 0, 0, 0, 0, 0, 0, 0, 0, 0]
    },
    "rationale": "Use own colour and coordinate parity. Demonstration 2 changes all 2s on even rows to 0, changes 1 at (2,2) to 9, and changes zeros at odd-row, odd-column positions such as (1,3), (1,5), and (3,1) to 1."
  }
]
